const cq = $('Telegram Trigger').first().json.callback_query;
const data = (cq.data || '').split(':');
const type = data[0];
const action = data[1] || null;
const projectId = data[2] || null;
const messageId = cq.message ? cq.message.message_id : null;
const chatId = cq.message ? cq.message.chat.id : null;
const callbackId = cq.id;

// The callback carries a Project id (v2). Validate it before interpolating:
// the Telegram button payload is user-controllable.
const valid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(projectId || '');

const projectRow = (stage) => `WITH p AS (
  SELECT id, artist_id FROM projects WHERE id = '${projectId}'::uuid
)
SELECT s.id, s.stage_key,
       l.phone_e164 AS telefone, l.name AS nome,
       a.wa_session_slug,
       COALESCE(NULLIF(st.display_name, ''), a.name) AS artista_nome,
       (SELECT ce.start_at FROM calendar_entries ce
         WHERE ce.project_id = p.id AND ce.kind = 'booking' AND ce.active
         ORDER BY ce.start_at DESC LIMIT 1) AS booked_date
FROM p
CROSS JOIN LATERAL set_project_stage(p.artist_id, p.id, '${stage}') s
JOIN projects pr ON pr.id = p.id
JOIN leads l ON l.id = pr.lead_id
JOIN artists a ON a.id = p.artist_id
LEFT JOIN artist_settings st ON st.artist_id = a.id;`;

const depositConfirm = `WITH p AS (
  SELECT id, artist_id FROM projects WHERE id = '${projectId}'::uuid
), c AS (
  SELECT p.id AS project_id, p.artist_id, pay.amount_cents, pay.status
  FROM p CROSS JOIN LATERAL confirm_deposit(p.artist_id, p.id, 'pix') pay
)
SELECT l.phone_e164 AS telefone, l.name AS nome,
       a.wa_session_slug,
       COALESCE(NULLIF(st.display_name, ''), a.name) AS artista_nome,
       (SELECT ce.start_at FROM calendar_entries ce
         WHERE ce.project_id = c.project_id AND ce.kind = 'booking' AND ce.active
         ORDER BY ce.start_at DESC LIMIT 1) AS booked_date
FROM c
JOIN projects pr ON pr.id = c.project_id
JOIN leads l ON l.id = pr.lead_id
JOIN artists a ON a.id = c.artist_id
LEFT JOIN artist_settings st ON st.artist_id = a.id;`;

const noop = 'SELECT NULL::uuid AS id;'

let query = noop;
let answerText = '';
let editText = '';

if (type === 'handoff') {
  if (action === 'confirm') {
    query = valid ? projectRow('fechado') : noop;
    answerText = '✅ Handoff aceito! Projeto movido para fechado.';
    editText = '<b>✅ Handoff aceito</b>';
  } else if (action === 'cancel') {
    query = valid ? projectRow('perdido') : noop;
    answerText = '❌ Handoff recusado. Projeto movido para perdido.';
    editText = '<b>❌ Handoff recusado</b>';
  }
} else if (type === 'deposit') {
  if (action === 'confirm') {
    query = valid ? depositConfirm : noop;
    answerText = '✅ Sinal confirmado! Prossiga com o agendamento.';
    editText = '<b>✅ Sinal Recebido — Pronto para agendamento</b>';
  } else if (action === 'cancel') {
    query = valid ? projectRow('perdido') : noop;
    answerText = '❌ Sinal não recebido. Projeto movido para perdido.';
    editText = '<b>❌ Sinal Não Recebido</b>';
  }
}

return [{ json: {
  type,
  action,
  project_id: projectId,
  answer_text: answerText,
  edit_text: editText,
  callback_id: callbackId,
  message_id: messageId,
  chat_id: chatId,
  query,
} }];

const parseData = $('Parse Callback').first().json;
const updated = $('Update Lead (Callback)').first().json;

const isDepositConfirm = parseData.type === 'deposit' && parseData.action === 'confirm';
if (!isDepositConfirm || !updated || !updated.telefone) {
  return [{ json: { send: false } }];
}

function fmtDate(iso) {
  const dias = ['domingo','segunda','terça','quarta','quinta','sexta','sábado'];
  const dt = new Date(iso);
  const parts = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'long', day: 'numeric', hour: 'numeric', hour12: false }).formatToParts(dt);
  let wd='', dia='', hora='';
  for (const p of parts) {
    if (p.type==='weekday') wd = p.value;
    if (p.type==='day') dia = p.value;
    if (p.type==='hour') hora = p.value;
  }
  return wd + ', dia ' + dia + ' às ' + hora + ' horas';
}

const artista = updated.artista_nome || 'artista';
const quando = updated.booked_date ? fmtDate(updated.booked_date) : null;
const text = quando
  ? 'Sinal recebido! Seu agendamento está confirmado para ' + quando + '. O ' + artista + ' te espera lá!'
  : 'Sinal recebido! Seu agendamento está confirmado. O ' + artista + ' te espera lá!';

return [{ json: { send: true, session: updated.wa_session_slug, chatId: updated.telefone + '@c.us', text } }];
